import type { Config } from 'tailwindcss'
import sharedConfig from '@repo/tailwind-config'

const config: Config = {
// 공유 설정의 모든 속성 상속
  ...sharedConfig,
// content 배열에 웹 앱의 경로 추가
  content: [
    ...(sharedConfig.content as string[]),// 타입 단언 사용
    './src/**/*.{js,ts,jsx,tsx,mdx}'
  ],
}

export default config

